// Two-tone 16-civ palette (icon-study). Generated by palette/mkmod.py from palette-v7.json (toned down).
// PAIR_DE[i][j]: min CIEDE2000 (normal/deutan/protan, badge-darkened) combined primary+secondary.
export const CIV_PALETTE_16=[{"color": "#96482c", "secondaryColor": "#909cd5"}, {"color": "#c1a08b", "secondaryColor": "#c9a39c"}, {"color": "#9c7154", "secondaryColor": "#e3dbb5"}, {"color": "#96732c", "secondaryColor": "#d59090"}, {"color": "#aa9646", "secondaryColor": "#b5e3db"}, {"color": "#a3b06d", "secondaryColor": "#9090d5"}, {"color": "#2c9681", "secondaryColor": "#90a7d5"}, {"color": "#6db0ac", "secondaryColor": "#90d5c9"}, {"color": "#446b7e", "secondaryColor": "#9ca3c9"}, {"color": "#80a8cb", "secondaryColor": "#a790d5"}, {"color": "#5182cd", "secondaryColor": "#b5cce3"}, {"color": "#909cea", "secondaryColor": "#a7d590"}, {"color": "#67549c", "secondaryColor": "#d5c990"}, {"color": "#b06da3", "secondaryColor": "#d59090"}, {"color": "#cb8094", "secondaryColor": "#d5d590"}, {"color": "#9c545d", "secondaryColor": "#90d5d5"}];
export const PAIR_DE=[[0, 22.5, 20.9, 15.4, 23.0, 22.2, 21.2, 35.9, 30.7, 34.5, 34.3, 39.3, 34.3, 26.5, 28.4, 16.0], [22.5, 0, 14.6, 15.8, 18.5, 14.8, 14.5, 15.4, 27.9, 24.8, 29.8, 26.2, 30.1, 22.5, 15.3, 21.7], [20.9, 14.6, 0, 14.7, 15.5, 25.7, 20.7, 25.3, 30.4, 34.3, 31.3, 29.4, 27.4, 25.3, 16.9, 14.7], [15.4, 15.8, 14.7, 0, 15.4, 20.3, 26.0, 29.8, 30.5, 34.9, 39.7, 39.2, 39.1, 34.5, 26.9, 21.8], [23.0, 18.5, 15.5, 15.4, 0, 19.0, 24.9, 24.1, 32.5, 36.4, 39.4, 40.4, 43.4, 40.4, 24.6, 22.6], [22.2, 14.8, 25.7, 20.3, 19.0, 0, 19.0, 23.4, 28.8, 29.0, 40.5, 43.3, 49.8, 39.3, 30.4, 26.6], [21.2, 14.5, 20.7, 26.0, 24.9, 19.0, 0, 15.0, 14.9, 19.0, 26.1, 31.9, 30.5, 17.9, 22.2, 15.1], [35.9, 15.4, 25.3, 29.8, 24.1, 23.4, 15.0, 0, 19.9, 17.6, 23.2, 20.6, 28.8, 14.9, 14.6, 22.5], [30.7, 27.9, 30.4, 30.5, 32.5, 28.8, 14.9, 19.9, 0, 14.7, 14.8, 26.5, 20.3, 14.6, 22.7, 15.0], [34.5, 24.8, 34.3, 34.9, 36.4, 29.0, 19.0, 17.6, 14.7, 0, 15.1, 23.4, 30.6, 14.7, 28.5, 30.5], [34.3, 29.8, 31.3, 39.7, 39.4, 40.5, 26.1, 23.2, 14.8, 15.1, 0, 17.7, 17.2, 17.0, 25.9, 27.4], [39.3, 26.2, 29.4, 39.2, 40.4, 43.3, 31.9, 20.6, 26.5, 23.4, 17.7, 0, 15.6, 17.5, 21.1, 27.6], [34.3, 30.1, 27.4, 39.1, 43.4, 49.8, 30.5, 28.8, 20.3, 30.6, 17.2, 15.6, 0, 14.6, 20.1, 22.4], [26.5, 22.5, 25.3, 34.5, 40.4, 39.3, 17.9, 14.9, 14.6, 14.7, 17.0, 17.5, 14.6, 0, 14.6, 17.3], [28.4, 15.3, 16.9, 26.9, 24.6, 30.4, 22.2, 14.6, 22.7, 28.5, 25.9, 21.1, 20.1, 14.6, 0, 15.8], [16.0, 21.7, 14.7, 21.8, 22.6, 26.6, 15.1, 22.5, 15.0, 30.5, 27.4, 27.6, 22.4, 17.3, 15.8, 0]];
const h2=h=>{const n=parseInt(String(h).slice(1,7),16);return [n>>16&255,n>>8&255,n&255];};
// Fallback for saves without secondaryColor: pale, slightly warm tint of the primary.
export function deriveSecondary(color){if(!/^#[0-9a-f]{6}$/i.test(String(color)))return '#d8c8a0';const c=h2(color),t=[232,220,190];return '#'+c.map((v,i)=>Math.round(v*.45+t[i]*.55).toString(16).padStart(2,'0')).join('');}
// Neighbour-aware: greedy permutation so the closest start pairs get the most distinct palette entries.
// dist(i,j) = map distance between player i and j starts. Deterministic (no RNG use).
export function assignCivPalette(n,dist){
  const N=Math.min(n,16),pairs=[];for(let i=0;i<N;i++)for(let j=i+1;j<N;j++)pairs.push([dist(i,j),i,j]);
  const crowd=Array.from({length:N},(_,i)=>pairs.filter(p=>p[1]===i||p[2]===i).reduce((sum,p)=>sum+1/(1+p[0]),0));
  const order=Array.from({length:N},(_,i)=>i).sort((a,b)=>crowd[b]-crowd[a]||a-b);
  const pick=Array(N).fill(-1),used=new Set();
  for(const i of order){let best=-1,bs=-Infinity;for(let k=0;k<16;k++){if(used.has(k))continue;let s=Infinity;for(let j=0;j<N;j++)if(pick[j]>=0){const w=PAIR_DE[k][pick[j]]*Math.sqrt(Math.max(1,dist(i,j)));s=Math.min(s,w);}if(s===Infinity)s=-k;if(s>bs){bs=s;best=k;}}pick[i]=best;used.add(best);}
  return pick.map(k=>CIV_PALETTE_16[k]);
}
